// Garbage collector
// =================
//
// The heap is one reserved region cut into 64 KB blocks. A small block holds
// slots of one size class; a large object takes whole blocks. Each block
// starts with a header holding an allocation and a mark bitmap. Every word
// of a live object, of a thread's stack and of the registered roots is read
// as a possible pointer; pointers into the middle of an object keep it too.
// A thread allocates from a private free list; the block behind that list
// is not swept until the thread moves on to another one.

#define GC_BLK_SHIFT 14
#define GC_BLK ((uintptr_t)1 << GC_BLK_SHIFT)
#define GC_MAXBLK ((uintptr_t)1 << 22)
#define GC_HDR 64
#define GC_SMALL 1024
#define GC_NCLS 43
// A block's allocation (and mark) bitmap, in words: a bit for each slot of
// the smallest class (2 words). (A 16 KB block holds at most 1020 slots.)
#define GC_BW 16
#define GC_MAXTHR 256
#define GC_SIG SIGUSR2

typedef struct GcBlk {
  uint32_t words;    // slot size (small) or object size (large), in words
  uint32_t nobj;     // slots in the block (1 for a large object)
  uint32_t nblk;     // blocks spanned
  uint8_t atomic;    // holds no pointers: never scanned
  uint8_t large;
  uint8_t owned;     // the caches holding it (or 1 being made, or gc_shr's 1): not swept, not claimed
  uint8_t cls;
  uint8_t pool;      // its caches' (Thr.cache): 0 nodes and closures, 1 atomic, 2 bare nodes
  uint32_t born;     // gc_epoch when it was made (small): no marks while it is unchanged
  struct GcBlk *next;
} GcBlk;

// What matches and the collector read most, by block index, in dense tables
// (a block's own header is a page away from most of its objects): a block's
// allocation and mark bits (gc_abits, gc_mbits: GC_BW words a block), and:
typedef struct GcMeta {
  uint32_t recip;    // 2^32 / slot bytes, rounded up: a slot's index by multiplying
                     // (exact for any byte of a block: the rounding adds less than
                     // 2^16 / 2^32 of a slot, and a slot is under 2^16 bytes)
  uint8_t large, cls;
  uint16_t words;    // slot size in words (small blocks; 0 for a large object)
} GcMeta;
_Static_assert(sizeof(GcBlk) <= GC_HDR, "GC_HDR holds a block header");
_Static_assert((GC_BLK - GC_HDR) / (2 * sizeof(uint64_t)) <= GC_BW * 64, "GC_BW words hold a bit for each slot of a block");

// A thread's allocation cache for one size class: a fresh block is handed out
// by bumping; a partly free one by the free bits of its bitmap, a word at a
// time (the slots are not touched until they are handed out).
// The cache holds up to 64 slots at a time, a word of the allocation bitmap:
// the slots from bump to end, or the free bits of word j. Their allocation
// bits are set when the cache takes them (gc_window), so handing one out is
// a bump or a bit taken (no bitmap write). A collection can then mark one it
// has not handed out yet (from a stale pointer), which would make the object
// later built there old; so every block a cache holds is dirty for the next
// collection (gc_dirty_caches), which rescans its old objects.
// bump, end, j, bits and objs are read and written by native code too (its
// allocation fast path; see rt/native.c): their offsets and the struct's
// size are fixed there.
typedef struct GcCache {
  V *bump; V *end;
  uint64_t *abits;  // GC_ALLOC(blk)
  uint32_t idx;     // bumping: the next word of the block to bump through (0: none)
  uint32_t j;
  uint64_t bits;    // free slots of word j
  V *objs;
  uint32_t nj;
  uint8_t reuse;    // the block came from the reuse queue: its slots are not new memory
  GcBlk *blk;
} GcCache;

struct PDeque;

// Classes of up to 16 words (nodes) reuse the slots matches free.
#define GC_RQCLS 15
#define ARR_SPARES 8

// A thread's caches by pool (GcBlk.pool): 0 for objects with a first word
// (nodes, closures, arrays), 1 for atomic objects, 2 for bare nodes (see
// "Bare nodes").
#define GC_NPOOL 4
typedef struct Thr {
  GcCache cache[GC_NPOOL][GC_NCLS];
  uint32_t rcur[GC_NCLS];   // where the next search for a reuse block starts
  size_t since;             // bytes handed out not yet added to gc_since
  // Its candidate bytes (see gc_cand), less the heap's first block index:
  // byte node >> GC_BLK_SHIFT is c + 1 when it freed a slot of class c in
  // the node's block, which it then reuses. Only it reads and writes them.
  uintptr_t candb;
  V *rcs; size_t rcn, rccap; // reference counting: the objects rc_free_obj has yet to free
  uintptr_t top;
  volatile uintptr_t sp;
  pthread_t id;
  _Atomic int live, parked;
  struct PDeque *dq;
  uint32_t rng;
  // Claiming a reuse block (gc_refill): a stop signal that comes meanwhile
  // is deferred (deferred is set) until the claim is over.
  volatile sig_atomic_t claiming, deferred;
  // Arrays the program is done with (arr_dead), for the next Array.new of
  // their class; a collection forgets them (arr_hook).
  V spare[ARR_SPARES];
  uint32_t nspare;
  uint64_t plast; // when a parallel let past its site's cutoff last forked (par_small)
  int pdepth;     // par_depth, where thr_get reaches it (see par_depth)
  // The nodes of up to 16 words it freed in the block its cache of their
  // pool and class allocates from: a list through their second words,
  // which allocation takes first (see rc_free_at, bend_free_slot).
  V *lifo[GC_NPOOL][GC_RQCLS];
} Thr;

