  // the node's offset in its block is its low 16 bits: no base to subtract)
  uintptr_t abits;
  // The first thread's candidate bytes (Thr.candb): a free is one byte
  // stored, candb[node >> GC_BLK_SHIFT] = class + 1.
  uintptr_t candb;
  int mt;
  int rc;  // reference counting (a program compiled with BEND_RC=1): no collections
  int rcmt; // rc and mt: a slot's allocation bit is set atomically
  // gc_dirty less the heap's first block index: a node's byte is
  // dirty[node >> GC_BLK_SHIFT], one shift (reuse tokens mark 3G blocks
  // dirty in a tree-bitonic run; the subtraction was 10G instructions)
  uintptr_t dirty;
  uint8_t *bk;  // gc_bk
  uintptr_t bflags;  // gc_bflags less the heap's first two-word index
  // Some bare node may be shared (a block got BK_SH, or the device's arena
  // was set): until then a take of a bare node tests no block's byte.
  int bsh;
  // A counted program with kind-8 constructors (bend_hless_req): a bare
  // node's count is its gc_bflags byte (see "Reference counting").
