// Parallel calls
// ==============
//
// A parallel let `a b = f(x) g(y)` forks every value but the last as a task
// (a closure applied to a dummy argument), evaluates the last one, then joins
// the tasks in reverse. Each thread owns a Chase-Lev deque: it pushes and
// pops at the bottom, idle threads steal from the top. A task nobody stole
// runs inline at its join, so a fork costs little more than a closure.
// Reference counted, a task is queued held (P_HELD): marking what its
// closure reaches (rc_publish) is paid for the tasks that are stolen only.
// A thief that finds the oldest task held asks its owner (want), which
// marks it and lets it go (P_QUEUED) at its next fork or join.

#define P_LOCAL 0
#define P_QUEUED 1
#define P_DONE 2
#define P_HELD 3
#define P_WAIT 4

typedef struct PTask { V clo; V res; V state; V depth; int *site; } PTask;

// The fork depth of the running code, and the frontier past which a def
// with a sequential clone (S_name, see bendc) runs its parallel lets in
// order: below it, forking costs more than it balances.
// (On arm64 Macs, a field of the thread's Thr: a Mach-O thread-local is
// a call to _tlv_get_addr, 2% of tree-matmul's samples, where thr_get is
// one load off the thread's TSD base, read once per function.)
#if defined(__APPLE__) && defined(__aarch64__) && !defined(__TINYC__)
#define par_depth (thr_get()->pdepth)
#elif !defined(__TINYC__)
extern __thread int par_depth;
#endif
extern int par_front;

typedef struct PDeque {
  _Atomic long top;
  _Atomic long bot;
  _Atomic int want;
  long mask;
  PTask **buf;
} PDeque;

extern int par_nthreads;
// The pool's size as effect sources name it (IO.thread_count).
#define pool_size ((u32)par_nthreads)
extern _Atomic int par_started;
extern pthread_mutex_t par_mu;
extern pthread_cond_t par_cv;
// Joiners that wait for a stolen task (P_WAIT) sleep on par_jcv.
extern pthread_cond_t par_jcv;
extern _Atomic int par_sleepers;
// Workers running a task they stole.
extern _Atomic int par_running;

// Task ages. A queued task holds the time it was forked (in res, until it
// is done), in units of 16 ticks since the pool started; a thief takes it
// only once it is par_age old.
#if defined(__aarch64__) && !defined(__TINYC__)
static inline uint64_t par_ticks(void) {
  uint64_t v;
  __asm__ __volatile__("mrs %0, cntvct_el0" : "=r"(v));
  return v;
}
uint64_t par_tick_hz(void);
#else
static inline uint64_t par_ticks(void) {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000000000u + (uint64_t)ts.tv_nsec;
}
uint64_t par_tick_hz(void);
#endif
extern uint64_t par_t0;
extern uint64_t par_age;
static inline uint64_t par_now(void) { return (par_ticks() - par_t0) >> 4; }

// Each parallel let has a cutoff (its site, a static int of the generated
// code): 0, or 1 + the fork depth from which it runs its values in order.
// Joining a task its forker ran itself tells how long the rest of the let
// took meanwhile: under par_age, the let's values are too small to fork at
// that depth and below; a task that waited longer, or that a thief took,
// lets its depth fork again. Past the cutoff, a thread still forks once
// every par_age, to find out whether the values grew.
static inline int par_small(int *site) {
  int c = __atomic_load_n(site, __ATOMIC_RELAXED);
  if (c == 0 || par_depth < c - 1) return 0;
  Thr *me = thr_self;
  uint64_t now = par_now();
  if (now - me->plast < par_age) return 1;
  me->plast = now;
  return 0;
}
static inline void par_site_small(int *site, int d) {
  int c = __atomic_load_n(site, __ATOMIC_RELAXED);
  if (c == 0 || c > d) __atomic_store_n(site, d, __ATOMIC_RELAXED);
}
static inline void par_site_big(int *site, int d) {
  int c = __atomic_load_n(site, __ATOMIC_RELAXED);
  if (c != 0 && c <= d) __atomic_store_n(site, d + 1, __ATOMIC_RELAXED);
}

// A deque holds at most 4 tasks (par_fork_at), and one more each side for a
// pop or a steal under way: 64 slots, after the PDeque in mem (THR_DQ bytes,
// zeros, in its thread's first page: see thr_stack).
#define PDQ_N 64
_Static_assert(sizeof(PDeque) <= 128 && 128 + PDQ_N * sizeof(PTask *) <= THR_DQ, "a deque fits THR_DQ");
PDeque *pdq_new(void *mem);

PTask *pdq_pop(PDeque *d);

// A steal that finds a task it cannot take yet (too young, or held) sets
// *pend.
PTask *pdq_steal(PDeque *d, int *pend);

void par_exec(PTask *t);

PTask *par_steal(int *pend);

static inline void cpu_relax(void) {
#if defined(__TINYC__)
  // tcc has no pause/yield: a plain spin
#elif defined(__x86_64__)
  __builtin_ia32_pause();
#elif defined(__aarch64__)
  __asm__ __volatile__("yield");
#endif
}

// An idle worker searches (PAR_SPIN rounds of steals over every deque), then
// sleeps (not while a task it saw is too young or held to take yet: it
// keeps searching until it can). A fork wakes a sleeper only when no worker
// is searching, and a searcher that finds a task wakes the next one: a
// program that forks small tasks often, with the other threads mostly
// idle, no longer has every fork wake a worker that spins and sleeps again,
// while a burst of forks still brings them all in. A sleeper also wakes
// every 2 ms (a wake-up can be missed: the fork reads par_sleepers without
// the lock), looks once and sleeps again. A task nobody steals is not lost:
// its forker runs it at the join.
#define PAR_SPIN 128
extern _Atomic int par_searching;

// macOS puts default-quality-of-service threads first in line for preemption
// and migration, which costs the pool ~10% of its cycles and time when
// anything else runs on the machine: 31.0G vs 33.4G cycles for tree-bitonic
// at 8 threads.  BEND_QOS=0 keeps the default class.
static inline void par_qos(void) {
#if defined(__APPLE__) && !defined(__TINYC__)
  const char *q = getenv("BEND_QOS");
  if (!q || q[0] != '0') pthread_set_qos_class_self_np(QOS_CLASS_USER_INTERACTIVE, 0);
#endif
}

void *par_worker(void *arg);

// The tasks queued in the deques (the slots from top to bot, and one more
// each side for a pop or a steal the collection stopped halfway; the rest
// are stale, and a task is held on its forker's stack until it is joined).
void par_hook(void);

void par_start(void);

// A thief asked (want): the oldest held task in this thread's deque d is
// marked and let go.
__attribute__((noinline)) void par_serve(PDeque *d);
static inline void par_serve_if(PDeque *d) {
  if (UNLIKELY(atomic_load_explicit(&d->want, memory_order_relaxed))) par_serve(d);
}

// Forks clo (a closure taking one dummy argument); returns the task. Only a
// thread whose deque is nearly empty queues it (the oldest tasks, which
// thieves take, are the big ones); otherwise the fork is the closure itself,
// tagged with bit 1, and its join just applies it.
V par_fork_at(int *site, V clo);

V par_fork(V clo);

// Waits for a forked task and returns its value.
V par_join(V tv);

int cpu_count(void);

// Effects
// =======
//
// An effect def compiles to a request node {cid | n << 24, args..., k}. The
// event loop runs each computation's pure code up to its next request, runs
// the effect's host function, then resumes k with the answer. The host
// functions use the official runtime's names and conventions: see
// EFFECTS.md in the Bend guide. A CID encodes how a constructor is laid out
// here: kind << 16 | tag, where kind 0 is a node, 1 a nullary constructor,
// 2 a single-field single-constructor type (the field itself), and 3 an
// effect (its tag is its row in io_eff_rows).

#ifndef CID_TUPLE
#define CID_TUPLE 0u
#endif
#ifndef CID_DONE
#define CID_DONE 1u
#endif
#ifndef CID_FAIL
#define CID_FAIL 0u
#endif
#ifndef CID_SOME
#define CID_SOME 1u
#endif
#ifndef CID_NONE
#define CID_NONE ((1u << 16) | 0u)
#endif
#ifndef CID_TRUE
#define CID_TRUE ((1u << 16) | 1u)
#endif
#ifndef CID_FALSE
#define CID_FALSE ((1u << 16) | 0u)
#endif
#ifndef CID_UNIT
#define CID_UNIT ((1u << 16) | 0u)
#endif

// A request node for effect cid with n fields (its arguments, then k).
static inline V io_req(u64 cid, int n, const V *xs) { return CN(cid | ((V)n << 24), n, xs); }

typedef struct { int unused; } Env;
typedef pthread_mutex_t lock;
#define OUTLINE __attribute__((noinline))
#define IO_READ 1
#define IO_TIME 2
#define IO_HELP 64
extern V io_hole_cell;
#define TERM_HOLE ((Term)(uintptr_t)&io_hole_cell)
#define IO_PARK TERM_HOLE
#define io_hand(v) ((Term)(v))
#define io_hand_v(t) ((u64)(t))
#define CID_KIND(c) ((u32)(c) >> 16)
#define CID_TAG(c) ((u32)(c) & 0xffff)

__attribute__((noreturn)) void err_fail(const char *msg);

static inline Term term_pak(u64 cid, Term v) {
  switch (CID_KIND(cid)) {
    case 1: return IMM(CID_TAG(cid));
    case 2: return v;
    case 7: return LI(CID_TAG(cid), v);
    default: return C1(CID_TAG(cid), v);
  }
}

// The CID of a constructor value (a node's or a nullary one's).
static inline u64 term_aux(Term t) { return (t & 1) ? ((t & 2) ? ((7u << 16) | (u32)((t & 0xffff) >> 3)) : ((1u << 16) | (u32)(t >> 3))) : (V)(uint32_t)((V *)t)[0] & ~BEND_SH_BITS; }
#define term_drop(e, t) ((void)(e), bend_drop(t))
#define term_sink(e, t) ((void)(e), bend_drop(t))
#define cls_fit(n) 0
